#!/usr/bin/env python3
"""Writes Slots.g.cs: the 64 global slot parameters of Neo Plug (docs/specs/plugin-host.md section 3.3)."""
import os

here = os.path.dirname(os.path.abspath(__file__))
lines = [
    "// <auto-generated> by Machines/NeoPlug/gen-slots.py. Do not edit.",
    "#nullable disable",
    "",
    "using Buzz.MachineInterface;",
    "",
    "namespace NeoBuzz.Plug",
    "{",
    "    public partial class NeoPlugMachine",
    "    {",
]
for i in range(1, 65):
    lines += [
        f'        [ParameterDecl(Name = "Slot {i}", Description = "A plug-in parameter (named once a plug-in is loaded)", MinValue = 0, MaxValue = 65534, DefValue = 0)]',
        f"        public int Slot{i} {{ get => core.SlotValue({i - 1}); set => core.SlotSet({i - 1}, value); }}",
        "",
    ]
lines += ["    }", "}", ""]
with open(os.path.join(here, "Slots.g.cs"), "w", newline="\n") as f:
    f.write("\n".join(lines))
